mapper.select:
select

from knowledge_base
where deleted = false

  and status <> #{excludeStatus}


  and status = #{status}


  and category = #{category}


  and (
  name ilike concat('%', #{keyword}, '%')
  or category ilike concat('%', #{keyword}, '%')
  or description ilike concat('%', #{keyword}, '%')
  )

order by updated_at desc, id asc
